        const w = Math.min(96, (W - 32) / L.leaves - 8);
        el('rect', { x: x - w / 2, y, width: w, height: leafH, rx: 12 }, g);
        el('text', { x, y: y + 21, 'text-anchor': 'middle', class: 'v' }, g).textContent = bad ? '불량' : '정상';
